mapper.select:
SELECT id, attachment_id, conversation_id, user_id, run_id, source_type,
       source_url, image_data, storage_provider, bucket_name, object_key, etag,
       mime_type, original_name, file_size, sha256, created_at
FROM ai_chat_attachment
WHERE attachment_id = #{attachmentId}
  AND (
    user_id = #{userId}
    OR conversation_id LIKE CONCAT('%:', #{userId}, ':%')
  )
LIMIT 1

SELECT id, attachment_id, conversation_id, user_id, run_id, source_type,
       source_url, image_data, storage_provider, bucket_name, object_key, etag,
       mime_type, original_name, file_size, sha256, created_at
FROM ai_chat_attachment
WHERE conversation_id = #{conversationId}
  AND (
    user_id = #{userId}
    OR conversation_id LIKE CONCAT('%:', #{userId}, ':%')
  )

